/* Local design-review prototype. No API, account, AI or messaging backend. */
(() => {
  'use strict';
  const screens = window.PROTOTYPE_SCREENS;
  const byKey = Object.fromEntries(screens.map(screen => [screen.key, screen]));
  const key = 'aiwrevolusi.designReview.v1';
  const initial = () => ({
    tasks: ['Update weekly sales records', 'Prepare a sales summary', 'Draft customer follow-up messages', 'Coach and coordinate my sales team'],
    foundation: 'With support', goal: 'Check whether an AI-written sales summary is accurate before sharing it with my team.',
    experience: 'I review sales reports and explain changes to my team.', saved: false, chapters: [0, 1, 2],
    minutes: 90, start: '2026-09-21', days: [1, 3], time: '20:30', sessions: [], events: [
      {id: 'care-wed', title: 'Bedtime routine', date: '2026-09-23', start: '20:15', end: '21:00', kind: 'care', shareable: true, help: ''},
      {id: 'personal-thu', title: 'Time for myself', date: '2026-09-24', start: '20:00', end: '20:30', kind: 'personal', shareable: false, help: ''},
    ], accountDemo: false, help: '', moved: false, careMode: false, message: 'Could you help with bedtime on Monday 21 September, from 20:15 to 21:00? I have a learning session from 20:30 to 21:00. Please let me know if that works for you?',
  });
  let state = initial();
  try { const stored = JSON.parse(localStorage.getItem(key)); if (stored && Array.isArray(stored.tasks) && Array.isArray(stored.events) && Array.isArray(stored.sessions)) state = {...state, ...stored}; } catch { /* A fresh review still works without storage. */ }
  const main = document.querySelector('#main');
  const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const note = text => `<div class="notice">${text}</div>`;
  const btn = (label, action, secondary = false) => `<button type="button" class="button${secondary ? ' secondary' : ''}" data-action="${action}">${esc(label)}</button>`;
  const link = (label, target, secondary = false) => `<button type="button" class="button${secondary ? ' secondary' : ''}" data-go="${target}">${esc(label)}</button>`;
  const field = (label, id, value, type = 'text', extra = '') => `<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${id}" type="${type}" value="${esc(value)}" ${extra}></div>`;
  const box = (title, body, extra = '') => `<section class="panel ${extra}"><h2>${title}</h2>${body}</section>`;
  const errorSlot = '<p class="error" id="form-error" role="alert"></p>';
  const selectedChapters = ['Start with a clear work task', 'Draft a summary', 'Check facts and missing context'];
  const today = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
  const dateOf = value => new Date(`${value}T12:00:00`);
  const iso = date => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
  const pretty = value => dateOf(value).toLocaleDateString('en-MY', {weekday: 'short', day: 'numeric', month: 'short'});
  const min = time => Number(time.split(':')[0]) * 60 + Number(time.split(':')[1]);
  const timeOf = value => `${String(Math.floor(value/60)).padStart(2,'0')}:${String(value%60).padStart(2,'0')}`;
  function toast(message) { const el = document.querySelector('#toast'); el.textContent = message; clearTimeout(toast.timer); toast.timer = setTimeout(() => { el.textContent = ''; }, 4500); }
  function save(next = state) { try { localStorage.setItem(key, JSON.stringify(next)); state = next; return true; } catch { toast('This browser could not save the change. Your previous saved state is kept.'); return false; } }
  function navigate(target) { if (!byKey[target]) target = 'home'; location.hash = target; if (current() === target) render(); }
  function current() { return location.hash.slice(1) || 'home'; }
  function fail(message) { const el = document.querySelector('#form-error'); if (el) el.textContent = message; else toast(message); }
  function panelCard(card) { return `<section class="panel screen-card"><p class="section-label">${esc(card[0])}</p><h2>${esc(card[1])}</h2><p class="body-copy">${esc(card[2])}</p></section>`; }
  function generic(screen) { return `<div class="workspace">${screen.cards.map(panelCard).join('')}</div><div class="actions">${screen.actions.map(([label,target],i) => link(label,target,i>0)).join('')}</div>`; }
  function home() { return `<div class="workspace hero-workspace"><section class="panel soft-panel"><p class="section-label">YOUR NEXT STEP, AT YOUR OWN PACE</p><h2>Understand the change.<br>Keep your experience.<br>Make a little room.</h2><p>Start with your daily work. Find one relevant learning opportunity. Fit it around the commitments that matter to you.</p><div class="actions">${link('Start free analysis','occupation')}${link('Try the learning journey','skills',true)}</div><p class="small">No CV. No account needed to begin.</p></section>${panelCard(screenCards('home')[1])}</div><ol class="review-map"><li><span>01</span>Describe your work</li><li><span>02</span>Understand task changes</li><li><span>03</span>Choose useful learning</li><li><span>04</span>Make a practical plan</li></ol>`; }
  function screenCards(id) { return byKey[id].cards; }
  function occupation() { return `<div class="workspace">${box('Find a match for your work', `${field('Search your job title','occupation-search','Sales supervisor')}<div id="occupation-result"><div class="course-row"><p class="section-label">EXAMPLE MATCH</p><h3>Sales Supervisor</h3><p>A starting point for reviewing your actual tasks.</p>${link('Use this occupation','tasks')}</div></div>`)}${box('Or browse a broad field', '<div class="field"><label for="occupation-category">Occupation category</label><select id="occupation-category"><option>Service and sales workers</option><option>Clerical support workers</option><option>Managers</option></select></div><p id="category-note">This review contains one sample occupation. The existing app provides the full MASCO catalogue.</p>','secondary-content')}</div>`; }
  function tasks() { return `<div class="workspace">${box(`${state.tasks.length} tasks in your work profile`, `<div id="task-list">${state.tasks.map((task,i) => `<div class="task-row"><input aria-label="Select task ${i+1}" type="checkbox" name="task-remove" value="${i}"><div class="field"><label for="task-${i}">Task ${i+1}</label><input id="task-${i}" data-task="${i}" value="${esc(task)}"></div><button class="button ghost" data-remove-task="${i}">Remove</button></div>`).join('')}</div><div class="actions">${btn('Add a task','add-task',true)}${btn('Remove selected','remove-selected',true)}</div>${errorSlot}<div class="actions">${btn('Assess my tasks','assess')}${link('Change occupation','occupation',true)}</div>`)}${box('Optional context', `<p>You can leave every field as Skip and continue.</p>${[['Frequency',['Skip','Daily','Several times a week','Weekly','Occasionally']],['Responsibility',['Skip','I do this myself','Shared with others','I lead others']],...['Routine processing','Information use','Human interaction','Judgement'].map(label=>[label,['Skip','Low','Medium','High']])].map(([label,options],i)=>`<div class="field"><label for="context-${i}">${label}</label><select id="context-${i}">${options.map(option=>`<option>${option}</option>`).join('')}</select></div>`).join('')}`,'secondary-content')}</div>`; }
  function impact() { return `${note('Illustrative result only. These example categories and scores are not live AI output or job-loss predictions.')}<div class="workspace">${box('Sales Supervisor', '<div class="stats"><div><strong>0.62</strong><span>Example exposure score</span></div><div><strong>Higher</strong><span>Example exposure level</span></div></div><p>A score needs context. Tool quality, workplace policy and your responsibilities affect how tasks change.</p><p>Source: prototype fixture. Actual occupation results must link to the supporting dataset.</p>'+link('Read the explanation','explanation',true))}${box('Review your tasks', `<div class="actions">${['All','AI support','Together','Human judgement'].map((label,i)=>`<button class="chip${i===0?' selected':''}" data-impact="${i}">${label}</button>`).join('')}</div><div id="impact-tasks">${impactRows(0)}</div>`)}</div><div class="actions">${link('See skills linked to my work','skills')}${link('Edit tasks and reassess','tasks',true)}</div>`; }
  function impactRows(filter) { const names=['AI support','Together','Human judgement']; return state.tasks.map((task,i) => ({task,category:i%3+1,score:[0.78,0.52,0.24][i%3]})).filter(row=>!filter||row.category===filter).map(row=>`<div class="course-row"><h3>${esc(row.task)}</h3><p>${names[row.category-1]} · Example score ${row.score}</p></div>`).join('') || '<p>No tasks in this example category.</p>'; }
  function focus() { return `<form id="focus-form"><div class="workspace">${box('Build on what you know', `<p class="section-label">ANALYTICAL THINKING</p><div class="field"><label for="foundation">Your starting point</label><select id="foundation">${['Just starting','With support','Independent','Advanced'].map(value=>`<option ${value===state.foundation?'selected':''}>${value}</option>`).join('')}</select></div><div class="field"><label for="experience">Relevant work experience</label><textarea id="experience" rows="4">${esc(state.experience)}</textarea></div><p>Your foundation is self-selected, not an assessment of your ability.</p>`)}${box('Choose your own learning goal', `<div class="field"><label for="goal">What would you like to be able to do?</label><textarea id="goal" rows="5" required>${esc(state.goal)}</textarea></div><p>Suggestions are drafts. You decide what to confirm.</p>${errorSlot}<button class="button" type="submit">Confirm focus and find courses</button>`)}</div></form>`; }
  function catalogue() { return `<div class="workspace"><aside class="panel secondary-content"><p class="section-label">YOUR CONFIRMED FOCUS</p><h2>Analytical thinking</h2><p><strong>${esc(state.foundation)}</strong></p><p>${esc(state.goal)}</p>${link('Edit my focus','focus',true)}<hr><h3>One step is enough</h3><p>Check content and requirements before committing your time.</p></aside><section class="panel"><div class="form-grid">${field('Search courses','course-search','')}<div class="field"><label for="level-filter">Level</label><select id="level-filter"><option value="all">All levels</option><option value="beginner">Beginner</option><option value="advanced">Advanced</option></select></div></div><p class="small">Example catalogue for design review; no provider facts are invented.</p><div id="course-results">${courseResult()}</div><div class="actions">${link(`Saved courses (${state.saved?1:0})`,'saved',true)}</div></section></div>`; }
  function courseResult() { return `<article class="course-row"><div class="actions"><span class="chip">Beginner example</span><span class="chip">Fictional course</span></div><h2>AI for everyday sales tasks</h2><p>Practise drafting a summary and checking it against its source.</p><p class="small">Provider duration: unknown · Access requirements: not supplied</p><div class="actions">${link('Review course','course')}${btn(state.saved?'Saved':'Save course','save-course',true)}</div></article>`; }
  function course() { return `<div class="workspace">${box('AI for everyday sales tasks', `<p class="section-label">FICTIONAL COURSE FOR REVIEW</p><p>Outcome example: draft a sales summary and check its claims against the original figures.</p><dl><dt>Provider duration</dt><dd>Unknown</dd><dt>Prerequisites</dt><dd>Not supplied</dd><dt>Access requirements</dt><dd>Not supplied</dd></dl><h3>Example chapters</h3><ol>${selectedChapters.map(chapter=>`<li>${chapter}</li>`).join('')}</ol><p class="small">No provider link is fabricated. Real course details must link to their source.</p>`)}${box('Practice it on a task you know', `<p class="section-label">ILLUSTRATIVE GUIDANCE</p><p>For your goal: <strong>${esc(state.goal)}</strong></p><ol><li>Use invented sales data.</li><li>Ask for a short summary.</li><li>Compare every number and claim with the source.</li><li>Record what you corrected and why.</li></ol><p>This is guidance, not an assessment of your ability.</p><div class="actions">${btn(state.saved?'View saved course':'Save course','save-and-open')}${link('Choose content and time','prepare',true)}</div>`)}</div>`; }
  function saved() { return `<div class="workspace">${box(state.saved?'1 saved course':'Your shortlist is empty', state.saved?`<div class="course-row"><h3>AI for everyday sales tasks</h3><p>Analytical thinking · Fictional example</p><p>${state.chapters.length} selected chapters · Your estimate: ${state.minutes} minutes</p><div class="actions">${link('Plan this course','prepare')}${btn('Remove from shortlist','remove-course',true)}</div></div>`:`<p>Save a resource that looks useful. Scheduled sessions remain in My Plan even if you remove a saved course.</p>${link('Browse learning resources','catalogue')}`)}${box('Keep a copy and return later', `<p>This review saves only in this browser, using a separate prototype storage key. It does not create an account or sync devices.</p><p>The production flow should offer sign-in when saving, after account-free analysis.</p><div class="actions">${btn('Export saved list','export',true)}${link('Open My Plan','calendar',true)}</div>`)}</div>`; }
  function prepare() { return `<form id="routine-form"><div class="workspace">${box('Choose the content you want', `<p class="section-label">FICTIONAL EXAMPLE COURSE</p><h3>AI for everyday sales tasks</h3>${selectedChapters.map((chapter,i)=>`<label class="check-row"><input name="chapter" type="checkbox" value="${i}" ${state.chapters.includes(i)?'checked':''}>${chapter}</label>`).join('')}<p>Provider duration: <strong>Unknown</strong></p>${field('My study-time estimate (minutes)','minutes',state.minutes,'number','min="1" max="6000" required')}<p class="small">Your estimate does not become a provider duration.</p>`)}${box('Make a little room in your week', `${field('Start date','start-date',state.start,'date','required')}${field('Study starts at','study-time',state.time,'time','required')}<p>Each study window is 30 minutes.</p><fieldset><legend>Study days</legend><div class="actions">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((day,i)=>`<label class="check-row"><input type="checkbox" name="day" value="${i}" ${state.days.includes(i)?'checked':''}>${day}</label>`).join('')}</div></fieldset>${errorSlot}<div class="actions"><button class="button" type="submit">Confirm routine</button>${btn('Schedule later','schedule-later',true)}</div><p class="small">The review uses exact 30-minute windows. The team must confirm whether that is the final rule.</p>`)}</div></form>`; }
  function sessionsNote() { const completed=state.sessions.filter(s=>s.complete).length;return `${completed} / ${state.sessions.length} sessions complete`; }
  function calendar() { const start=dateOf(state.start); const offset=(start.getDay()+6)%7;start.setDate(start.getDate()-offset);const days=Array.from({length:7},(_,i)=>{const date=new Date(start);date.setDate(date.getDate()+i);return iso(date);});return `<div class="actions">${btn('Add an everyday activity','new-activity')}${btn('Try a care conflict','make-conflict',true)}${link('Prepare a course','prepare',true)}</div>${state.sessions.length?'':note('No dated learning sessions yet. Set a routine, or leave a saved course for later.')}<div class="calendar-grid" aria-label="Weekly calendar">${days.map(date=>{const weekday=dateOf(date).getDay();const events=state.events.filter(e=>e.date===date);const sessions=state.sessions.filter(s=>s.date===date);return `<section class="day"><h2>${pretty(date)}</h2>${weekday>0&&weekday<6?'<div class="event work"><strong>Work</strong><span>09:00–17:00</span><small>Example hours</small></div>':''}${events.map(event=>`<button class="event ${event.kind}" data-event="${esc(event.id)}"><strong>${esc(event.title)}</strong><span>${event.start}–${event.end}</span><small>${event.help==='accepted'?'Helper responsible':event.help==='waiting'?'Waiting · still yours':'Your commitment'}</small></button>`).join('')}${sessions.map(session=>`<button class="event learning" data-session="${session.id}"><strong>${session.complete?'Completed':'Learning'}</strong><span>${session.start}–${session.end}</span><small>AI for everyday sales tasks</small></button>`).join('')}${!events.length&&!sessions.length?'<p class="small">Room to pause</p>':''}</section>`;}).join('')}</div><div class="workspace">${box('Your learning progress', `<h3>${sessionsNote()}</h3><div class="progress-track"><span style="width:${state.sessions.length?100*state.sessions.filter(s=>s.complete).length/state.sessions.length:0}%"></span></div><p>Last scheduled date: ${state.sessions.length?pretty(state.sessions[state.sessions.length-1].date):'Not scheduled'}</p><p>Work, care and personal activities are excluded.</p>${link('Review a learning session','progress',true)}`)}${box('All planned learning', state.sessions.length?state.sessions.map(s=>`<div class="course-row"><strong>${pretty(s.date)}</strong> · ${s.start}–${s.end}<span> · ${s.complete?'Complete':'Planned'}</span></div>`).join(''):'<p>Saved for later? Choose a routine when you are ready.</p>','secondary-content')}</div>`; }
  function schedule() { const picked=[...document.querySelectorAll('[name="chapter"]:checked')].map(el=>Number(el.value));const days=[...document.querySelectorAll('[name="day"]:checked')].map(el=>Number(el.value));const minutes=Number(document.querySelector('#minutes').value);const start=document.querySelector('#start-date').value;const time=document.querySelector('#study-time').value;if(!picked.length)return fail('Select at least one chapter.');if(!Number.isFinite(minutes)||minutes<=0||minutes>6000)return fail('Enter a study estimate from 1 to 6,000 minutes.');if(!start||start<today())return fail('Choose a start date that is today or later.');if(!days.length)return fail('Choose at least one study day.');if(!time||min(time)+30>1440)return fail('Choose a start time that leaves a 30-minute window before midnight.');if(state.sessions.length)return fail('This course already has scheduled sessions. Open My Plan to change them.');const sessions=[];let remaining=minutes;for(let offset=0;offset<365&&remaining>0;offset++){const date=dateOf(start);date.setDate(date.getDate()+offset);const value=iso(date);if(!days.includes(date.getDay()))continue;const begin=min(time);const duration=Math.min(30,remaining);const end=begin+duration;const weekday=date.getDay();const workOverlap=weekday>0&&weekday<6&&begin<17*60&&end>9*60;const overlaps=state.events.some(e=>e.date===value&&e.help!=='accepted'&&begin<min(e.end)&&end>min(e.start));if(workOverlap||overlaps)continue;sessions.push({id:`learning-${offset}`,date:value,start:time,end:timeOf(end),complete:false});remaining-=duration;}if(!sessions.length)return fail('No free study windows in the next year. Adjust the days or time; nothing was added.');if(!save({...state,chapters:picked,days,minutes,start,time,saved:true,sessions}))return; navigate('calendar');toast(remaining?`${sessions.length} sessions added. ${remaining} minutes still need a free window.`:`${sessions.length} sessions added. Busy windows were skipped.`); }
  let selectedSession = null;
  function progress(completeView=false) {const session=state.sessions.find(s=>s.id===selectedSession)||state.sessions[0];if(!session)return box('No session scheduled yet', `<p>Choose a study routine to try the progress flow.</p>${link('Prepare learning','prepare')}`);return `<div class="workspace">${box('Start with a clear work task', `<p class="section-label">${esc(pretty(session.date))} · ${session.start}–${session.end}</p><h3>AI for everyday sales tasks</h3><p>Status: <strong>${session.complete?'Complete':'Planned'}</strong></p><p>Use invented sales data, compare a summary with its source and record what you corrected.</p><div class="actions">${btn(session.complete?'Undo completion':'Mark session complete','toggle-complete')}${btn('Simulate a save failure','save-failure',true)}</div>`)}${box('Your progress', `<h2>${sessionsNote()}</h2><p>Last scheduled date: ${pretty(state.sessions[state.sessions.length-1].date)}</p><p>Everyday activities are excluded. A failed save leaves the last recorded progress unchanged.</p>${link('Return to My Plan','calendar',true)}`)}</div>`; }
  function help() { return `<div class="workspace">${box('Help with bedtime on Monday?', `<div class="field"><label for="help-message">Review and edit your message</label><textarea id="help-message" rows="7">${esc(state.message)}</textarea></div><a class="button secondary" id="whatsapp-link" href="https://wa.me/?text=${encodeURIComponent(state.message)}" target="_blank" rel="noopener noreferrer">Open WhatsApp</a><p class="small">You select a recipient and send in WhatsApp. Opening it does not send or confirm delivery.</p>`)}${box('Record the reply yourself', `<p>Until you record acceptance, you remain responsible. This review never reads a reply or contacts a helper.</p><div class="actions">${btn('Record waiting','help-waiting',true)}${btn('Record accepted','help-accepted')}${btn('Record declined','help-declined',true)}</div>${link('Back to conflict','conflict',true)}`)}</div>`; }
  function care() { return `<div class="workspace">${box('One useful thing is enough today', '<p>Check one sentence in an AI-written summary against the original figures.</p><p>Return to the rest when you have a little room.</p>'+link('Continue my learning','progress'))}${box('You control the pace', `<label class="check-row"><input id="care-mode" type="checkbox" ${state.careMode?'checked':''}>Show a simpler view</label><p>Language: English. Other languages need team agreement and translation review.</p><p>Reminder preference: Paused.</p><p class="small">Future concept. No reminders or subscriptions are activated.</p>`)}</div>`; }
  function assistance() { const event=state.events.find(e=>e.id==='demo-conflict');const session=state.sessions[0];if(!event||!session)return box('Try the conflict with your plan', '<p>Add a study routine first, then choose Try a care conflict in My Plan.</p>'+link('Open My Plan','calendar'));const accepted=event.help==='accepted';return `<div class="workspace">${box(accepted?'Helper responsible':event.help==='waiting'?'Waiting · still your responsibility':'Two activities at the same time', `<p class="section-label">${pretty(event.date)}</p><h3>${esc(event.title)}</h3><p>${event.start}–${event.end}</p><p>Status: ${esc(event.help||'No help recorded')}</p><hr><h3>AI for everyday sales tasks</h3><p>${session.start}–${session.end}</p><p>${accepted?'Acceptance was recorded by you.':'The care activity remains your responsibility.'}</p>`)}${box('You decide what happens next', `<p>Requesting help does not transfer responsibility. Record acceptance only after the helper agrees.</p><div class="actions">${accepted?link('Open learning session','progress'):link('Prepare request for help','help')}${btn('Record accepted','help-accepted',true)}${btn('Record waiting','help-waiting',true)}${btn('Record declined','help-declined',true)}</div><p class="small">Editing the arrangement clears the assistance record and asks you to contact the helper.</p>${link('Return to My Plan','calendar',true)}`)}</div>`; }
  const views={home,occupation,tasks,impact,focus,catalogue,course,saved,prepare,calendar,progress,complete:()=>progress(true),help,care,conflict:assistance,waiting:assistance,accepted:assistance};
  function render() { const route=byKey[current()]?current():'home';const screen=byKey[route];document.body.classList.toggle('care-mode',state.careMode);main.innerHTML=`<header class="page-heading"><p class="stage">${esc(screen.step)}</p><h1>${esc(screen.title)}</h1><p>${esc(screen.sub)}</p></header>${views[route]?views[route]():note('Illustrative review state. This screen shows an example, rather than the current saved values.')+generic(screen)}`;document.querySelectorAll('nav [data-go]').forEach(el=>el.setAttribute('aria-current',el.dataset.go===route?'page':'false'));document.querySelectorAll('#journey-links [data-go]').forEach(el=>el.classList.toggle('selected',el.dataset.go===route));main.focus({preventScroll:true});window.scrollTo(0,0); }
  function newConflict() { if(!state.sessions.length){navigate('prepare');toast('Schedule a course first, then try the conflict.');return;}const session=state.sessions[0];const events=state.events.filter(e=>e.id!=='demo-conflict');events.push({id:'demo-conflict',title:'Bedtime routine',date:session.date,start:timeOf(Math.max(0,min(session.start)-15)),end:session.end,kind:'care',shareable:true,help:''});if(save({...state,events,help:''})){navigate('conflict');toast('A sample care commitment now overlaps your first session.');} }
  function recordHelp(status) { const event=state.events.find(e=>e.id==='demo-conflict');if(!event){toast('Create the sample conflict in My Plan first.');navigate('calendar');return;}if(save({...state,help:status,events:state.events.map(e=>e.id===event.id?{...e,help:status}:e)})){navigate(status==='accepted'?'accepted':status==='waiting'?'waiting':'conflict');toast(status==='accepted'?'Acceptance recorded by you. The helper is responsible.':'You remain responsible for this activity.');} }
  function exportSaved() { const list=state.saved?[{title:'AI for everyday sales tasks',example:true,skill:'Analytical thinking',chapters:state.chapters.map(i=>selectedChapters[i]),providerDuration:null,userEstimateMinutes:state.minutes,providerUrl:null}]:[];const blob=new Blob([JSON.stringify(list,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='ai-wrevolusi-example-saved-courses.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exported the complete example saved list. Your plan is unchanged.'); }
  function activityDialog(id) { const event=state.events.find(e=>e.id===id);const date=event?.date||state.start;const dialog=document.createElement('dialog');dialog.className='activity-dialog';dialog.innerHTML=`<form id="activity-form"><h2>${event?'Edit this occurrence':'Add an everyday activity'}</h2>${field('Title','event-title',event?.title||'')}${field('Date','event-date',date,'date')}${field('Start','event-start',event?.start||'20:15','time')}${field('End','event-end',event?.end||'21:00','time')}<div class="field"><label for="event-kind">Type</label><select id="event-kind">${['care','work','personal'].map(type=>`<option ${event?.kind===type?'selected':''}>${type}</option>`).join('')}</select></div><label class="check-row"><input id="event-shareable" type="checkbox" ${event?.shareable?'checked':''}>I can ask for help with this activity</label>${event?'':'<label class="check-row"><input id="event-repeat" type="checkbox">Repeat weekly for four weeks</label>'}<p class="error" id="event-error" role="alert"></p><div class="actions"><button class="button" type="submit">Save activity</button><button class="button secondary" type="button" id="cancel-activity">Cancel</button>${event?'<button class="button ghost" type="button" id="delete-activity">Delete this occurrence</button>':''}</div></form>`;document.body.append(dialog);dialog.showModal();dialog.addEventListener('close',()=>dialog.remove());dialog.querySelector('#cancel-activity').onclick=()=>dialog.close();if(event)dialog.querySelector('#delete-activity').onclick=()=>{if(window.confirm('Delete only this occurrence? Other activities stay in your plan.')){if(save({...state,events:state.events.filter(e=>e.id!==event.id)})){dialog.close();render();}}};dialog.querySelector('form').onsubmit=ev=>{ev.preventDefault();const title=dialog.querySelector('#event-title').value.trim();const date=dialog.querySelector('#event-date').value;const start=dialog.querySelector('#event-start').value;const end=dialog.querySelector('#event-end').value;if(!title||!date||!start||!end||end<=start){dialog.querySelector('#event-error').textContent='Enter a title, valid date, and end time after start.';return;}const shareable=dialog.querySelector('#event-shareable').checked;const kind=dialog.querySelector('#event-kind').value;const changed=event&&(title!==event.title||date!==event.date||start!==event.start||end!==event.end||shareable!==event.shareable);let events=state.events.filter(e=>e.id!==event?.id);const count=!event&&dialog.querySelector('#event-repeat')?.checked?4:1;for(let i=0;i<count;i++){const day=dateOf(date);day.setDate(day.getDate()+i*7);events.push({id:event?.id||`event-${Date.now()}-${i}`,title,date:iso(day),start,end,kind,shareable,help:changed?'':event?.help||''});}if(save({...state,events})){dialog.close();render();toast(changed&&event.help?'Earlier assistance cleared. Contact your helper about the change.':'Activity saved. Other occurrences are unchanged.');}}; }
  document.addEventListener('click',event=>{const go=event.target.closest('[data-go]');if(go){if(go.textContent==='Move learning to 21:00'){const session=state.sessions[0];if(session){const sessions=state.sessions.map((s,i)=>i===0?{...s,start:'21:00',end:'21:30'}:s);if(!save({...state,sessions,moved:true}))return;}}navigate(go.dataset.go);return;}const remove=event.target.closest('[data-remove-task]');if(remove){state.tasks.splice(Number(remove.dataset.removeTask),1);save();render();return;}const eventBtn=event.target.closest('[data-event]');if(eventBtn){activityDialog(eventBtn.dataset.event);return;}const sessionBtn=event.target.closest('[data-session]');if(sessionBtn){selectedSession=sessionBtn.dataset.session;navigate('progress');return;}const impactBtn=event.target.closest('[data-impact]');if(impactBtn){document.querySelectorAll('[data-impact]').forEach(el=>el.classList.toggle('selected',el===impactBtn));document.querySelector('#impact-tasks').innerHTML=impactRows(Number(impactBtn.dataset.impact));return;}const action=event.target.closest('[data-action]')?.dataset.action;if(!action)return;switch(action){case'add-task':state.tasks.push('');save();render();document.querySelector(`[data-task="${state.tasks.length-1}"]`)?.focus();break;case'remove-selected':{const remove=new Set([...document.querySelectorAll('[name="task-remove"]:checked')].map(el=>Number(el.value)));save({...state,tasks:state.tasks.filter((_,i)=>!remove.has(i))});render();break;}case'assess':if(!state.tasks.length)return fail('Add at least one work task before starting.');if(state.tasks.some(task=>task.trim().split(/\s+/).length<3))return fail('Describe each task clearly in at least three words for this example.');save();navigate('impact');break;case'save-course':save({...state,saved:true});render();toast('Example course added to your shortlist.');break;case'save-and-open':save({...state,saved:true});navigate('saved');break;case'remove-course':save({...state,saved:false});render();toast('Removed from shortlist. Scheduled sessions are kept.');break;case'export':exportSaved();break;case'schedule-later':{const chapters=[...document.querySelectorAll('[name="chapter"]:checked')].map(el=>Number(el.value));if(!chapters.length)return fail('Select at least one chapter.');if(state.sessions.length)return fail('Already scheduled. Change this course in My Plan.');const minutes=Number(document.querySelector('#minutes').value);if(save({...state,chapters,minutes:Number.isFinite(minutes)&&minutes>0?minutes:0,saved:true})){navigate('later');toast('Selected content kept. No dated sessions added.');}break;}case'make-conflict':newConflict();break;case'new-activity':activityDialog();break;case'help-waiting':recordHelp('waiting');break;case'help-accepted':recordHelp('accepted');break;case'help-declined':recordHelp('declined');break;case'toggle-complete':{const session=state.sessions.find(s=>s.id===selectedSession)||state.sessions[0];if(session&&save({...state,sessions:state.sessions.map(s=>s.id===session.id?{...s,complete:!s.complete}:s)})){render();toast(session.complete?'Completion undone.':'Session completed and saved in this browser.');}break;}case'save-failure':toast('Simulated save failure. Your recorded completion and counts have not changed.');break;}});
  document.addEventListener('input',event=>{const el=event.target;if(el.matches('[data-task]')){state.tasks[Number(el.dataset.task)]=el.value;save();}if(el.id==='course-search'||el.id==='level-filter'){const query=document.querySelector('#course-search').value.toLowerCase();const level=document.querySelector('#level-filter').value;document.querySelector('#course-results').innerHTML=(level!=='advanced'&&'ai for everyday sales tasks analytical thinking'.includes(query))?courseResult():`<div class="empty"><h3>No matching courses</h3><p>Try another search or clear the advanced-level filter. Your learning focus is kept.</p></div>`;}if(el.id==='occupation-search')document.querySelector('#occupation-result').innerHTML='sales supervisor'.includes(el.value.toLowerCase())?`<div class="course-row"><h3>Sales Supervisor</h3><p>Example MASCO match</p>${link('Use this occupation','tasks')}</div>`:'<p>No match in this sample. Try “sales”. The existing app has the full catalogue.</p>';if(el.id==='help-message'){state.message=el.value;save();document.querySelector('#whatsapp-link').href=`https://wa.me/?text=${encodeURIComponent(el.value)}`;}});
  document.addEventListener('change',event=>{if(event.target.id==='care-mode'){save({...state,careMode:event.target.checked});document.body.classList.toggle('care-mode',state.careMode);}if(event.target.id==='occupation-category')document.querySelector('#category-note').textContent=event.target.value==='Service and sales workers'?'Sales Supervisor is available in this sample.':'No example occupations in this category. Choose Service and sales workers to continue.';});
  document.addEventListener('submit',event=>{if(event.target.id==='routine-form'){event.preventDefault();schedule();}if(event.target.id==='focus-form'){event.preventDefault();const goal=document.querySelector('#goal').value.trim();if(!goal)return fail('Enter a learning goal in your own words.');if(save({...state,goal,foundation:document.querySelector('#foundation').value,experience:document.querySelector('#experience').value.trim()}))navigate('catalogue');}});
  document.querySelector('#wireframe-toggle').onclick=event=>{const on=document.body.classList.toggle('wireframe');event.currentTarget.setAttribute('aria-pressed',String(on));event.currentTarget.textContent=on?'Show polished design':'Show wireframes';};
  document.querySelector('#journey-toggle').onclick=event=>{const panel=document.querySelector('#journey-panel');panel.hidden=!panel.hidden;event.currentTarget.setAttribute('aria-expanded',String(!panel.hidden));};
  document.querySelector('#reset-demo').onclick=()=>{if(window.confirm('Reset only this design prototype’s example data?')){if(save(initial())){selectedSession=null;navigate('home');toast('Prototype reset. The existing app is unchanged.');}}};
  document.querySelector('#journey-links').innerHTML=screens.map(screen=>`<button class="screen-link" data-go="${screen.key}"><span>${esc(screen.step)}</span>${esc(screen.title)}</button>`).join('');
  window.addEventListener('hashchange',render);
  document.querySelector('.skip-link').addEventListener('click', event => { event.preventDefault(); main.focus(); main.scrollIntoView(); });
  render();
})();
